def digit_sum(n):

    """ Find the sum of the digits of integer n. """
    s_digits = list(str(n)) dsum = 0
    for s_digit in s_digits:
        dsum += int(s_digit) 

def is_harshad(n):
    return not n % digit_sum(n)
